import { test, expect } from "bun:test";
import { readFileSync } from "fs";
import { join } from "path";
import { decode, encode, type Envelope } from "./envelope";
import { subjects } from "./subjects";
import { MailboxStats, RefuseError, refusedReply, tooLargeReply } from "./thrall";
import { expiredReply } from "./deadline";

// Golden fixtures are generated by the Go source of truth
// (internal/wire: `go test -run TestEnvelopeGolden -update`) and shared by all three SDKs.
const goldenDir = join(import.meta.dir, "../../../testdata/wire");
const golden = (name: string) => readFileSync(join(goldenDir, `${name}.json`));
const parse = (buf: Uint8Array) => JSON.parse(new TextDecoder().decode(buf));

// The same logical cases as goldenCases() in internal/wire/envelope_test.go. Constructing
// them through the typed Envelope shape means a renamed or retyped field fails to line up
// with the golden fixture.
const cases: Record<string, Envelope> = {
  call: { v: 1, id: "c-1", kind: "call", to: "counter", op: "get", payload: { n: 1 }, ts: 1700000000000 },
  call_traced: { v: 1, id: "c-9", trace: "t-abc", kind: "call", to: "counter", op: "get", payload: { n: 1 }, ts: 1700000000004 },
  call_idem: { v: 1, id: "c-10", idem: "withdraw-42", kind: "call", to: "account", op: "withdraw", payload: { amt: 5 }, ts: 1700000000005 },
  cast: { v: 1, id: "c-2", kind: "cast", to: "counter", op: "inc", payload: {}, ts: 1700000000001 },
  reply_ok: { v: 1, id: "c-1", kind: "reply", status: "ok", payload: { value: 42 } },
  reply_error: {
    v: 1, id: "c-1", kind: "reply", status: "error",
    error: { type: "unknown_op", message: "unknown call op: nope", retryable: false },
  },
  hb: { v: 1, kind: "hb", to: "counter", ts: 1700000000002 },
  hb_metrics: {
    v: 1, kind: "hb", to: "counter",
    payload: { mailbox_depth: 2, mailbox_latency_ms: 1.5, processed_total: 10 },
    ts: 1700000000003,
  },
  hb_describe: {
    v: 1, kind: "hb", to: "counter",
    payload: {
      mailbox_depth: 0, mailbox_latency_ms: 0, processed_total: 3,
      describe: {
        call_ops: ["get", "value"], cast_ops: ["inc", "reset"], version: "1.2.0",
        last_error: "handler_error: boom", last_error_ms: 1700000000005,
      },
    },
    ts: 1700000000006,
  },
  ctl: { v: 1, kind: "ctl", op: "drain" },
  minimal: { v: 1, kind: "call" },
  call_deadline: {
    v: 1, id: "c-11", trace: "t-abc", kind: "call", to: "account", op: "withdraw",
    payload: { amt: 5 }, ts: 1700000000007, deadline: 1700000005007,
  },
  reply_refused: {
    v: 1, id: "c-11", kind: "reply", status: "error",
    error: { type: "refused", code: "insufficient_funds", message: "the balance is 3, the withdrawal 5", retryable: false },
  },
  reply_deadline_exceeded: {
    v: 1, id: "c-11", kind: "reply", status: "error",
    error: { type: "deadline_exceeded", message: "call expired 1200 ms before it could be handled", retryable: true },
  },
  reply_too_large: {
    v: 1, id: "c-11", kind: "reply", status: "error",
    error: { type: "reply_too_large", message: "reply of 1500000 bytes does not fit one bus message (at most 1048576 bytes)", retryable: false },
  },
  hb_expired: {
    v: 1, kind: "hb", to: "account",
    payload: { mailbox_depth: 1, mailbox_latency_ms: 0.5, processed_total: 7, expired_total: 2 },
    ts: 1700000000008,
  },
};

for (const [name, env] of Object.entries(cases)) {
  test(`encodes ${name} to the canonical wire form`, () => {
    // Field order differs from Go, so compare parsed values, not bytes.
    expect(parse(encode(env))).toEqual(parse(golden(name)));
  });

  test(`round-trips ${name} through decode/encode`, () => {
    const decoded = decode(golden(name));
    expect(parse(encode(decoded))).toEqual(parse(golden(name)));
  });
}

test("subject convention matches the contract", () => {
  const app = "demo", name = "counter";
  expect(subjects.call(app, name)).toBe("aether.demo.counter.call");
  expect(subjects.cast(app, name)).toBe("aether.demo.counter.cast");
  expect(subjects.info(app, name)).toBe("aether.demo.counter.info");
  expect(subjects.data(app, name)).toBe("aether.demo.counter.*");
  expect(subjects.stream(app, name)).toBe("aether_demo_counter");
  expect(subjects.eventLog(app, name)).toBe("aether.demo.counter.evt");
  expect(subjects.eventLogStream(app, name)).toBe("aether_demo_counter_evt");
  expect(subjects.ctl(name)).toBe("aether._lord.counter.ctl");
  expect(subjects.hb(name)).toBe("aether._lord.counter.hb");
  expect(subjects.lordCtl()).toBe("aether._lord.ctl");
  expect(subjects.events).toBe("aether._lord.events");
});

// The replies the SDK itself builds must be the canonical wire form too: the refusal a handler's
// refuse() produces, the answer to a call dropped past its deadline and the stand-in for a reply
// too large to send.
test("the SDK builds the canonical refusal, deadline and too-large replies", () => {
  const req: Envelope = { v: 1, id: "c-11", kind: "call", op: "withdraw" };
  const refusal = new RefuseError("insufficient_funds", "the balance is 3, the withdrawal 5");
  expect(parse(encode(refusedReply(req, refusal)))).toEqual(parse(golden("reply_refused")));
  expect(parse(encode(expiredReply(req, 1200)))).toEqual(parse(golden("reply_deadline_exceeded")));
  expect(parse(encode(tooLargeReply(req, 1500000, 1048576)))).toEqual(parse(golden("reply_too_large")));
});

// A thrall that never dropped a call reports the heartbeat payload it always did (no
// expired_total key), and one that did reports the golden shape.
test("the heartbeat metrics payload matches the contract", () => {
  const stats = new MailboxStats();
  expect(Object.keys(stats.snapshot())).toEqual(["mailbox_depth", "mailbox_latency_ms", "processed_total"]);
  stats.begin();
  stats.drop();
  stats.begin();
  stats.drop();
  expect(stats.snapshot()).toEqual({ mailbox_depth: 0, mailbox_latency_ms: 0, processed_total: 0, expired_total: 2 });
});
